CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE COLLATE NOCASE,display_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','editor','viewer')),password_hash TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,must_change_password INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,last_seen TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS records(key TEXT PRIMARY KEY,value TEXT NOT NULL,version INTEGER NOT NULL,updated_at TEXT NOT NULL,updated_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO meta VALUES('revision','0');
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,at TEXT NOT NULL,actor_id TEXT,actor_name TEXT NOT NULL,action TEXT NOT NULL,record_key TEXT,fields TEXT NOT NULL DEFAULT '[]',version INTEGER);
CREATE TABLE IF NOT EXISTS login_attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,window_start TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS write_guards(id TEXT PRIMARY KEY,ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL UNIQUE,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_policies(source_id TEXT PRIMARY KEY REFERENCES sources(id),robots_reviewed INTEGER NOT NULL DEFAULT 0,terms_reviewed INTEGER NOT NULL DEFAULT 0,reviewed_at TEXT,reviewed_by TEXT,robots_url TEXT,terms_url TEXT,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS observations(id INTEGER PRIMARY KEY AUTOINCREMENT,source_id TEXT NOT NULL REFERENCES sources(id),observed_at TEXT NOT NULL,content_hash TEXT NOT NULL,summary TEXT NOT NULL,changed INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS opportunities(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),title TEXT NOT NULL,source_url TEXT NOT NULL,opens_at TEXT,closes_at TEXT,verified_open INTEGER NOT NULL DEFAULT 0,confirmed_closed INTEGER NOT NULL DEFAULT 0,review_status TEXT NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','approved','rejected')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,at TEXT NOT NULL,kind TEXT NOT NULL,reference_id TEXT NOT NULL,detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scan_runs(id TEXT PRIMARY KEY,started_at TEXT NOT NULL,ended_at TEXT,checked INTEGER NOT NULL DEFAULT 0,succeeded INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS alerts(id INTEGER PRIMARY KEY AUTOINCREMENT,dedupe_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,reference_id TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL,acknowledged_at TEXT);
CREATE TABLE IF NOT EXISTS evidence(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),url TEXT NOT NULL,content_hash TEXT NOT NULL,excerpt TEXT NOT NULL,opens_at TEXT,closes_at TEXT,conflicts INTEGER NOT NULL DEFAULT 0,review_status TEXT NOT NULL DEFAULT 'pending',reviewed_by TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scan_lock(id INTEGER PRIMARY KEY CHECK(id=1),owner TEXT,expires_at INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO scan_lock(id,expires_at) VALUES(1,0);
